import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for {@link Line#revert()}.
 */
public class Line_revert_TriageGen1Test {

    @Test
    public void testRevert() {
        // Define two points to create a line
        Vector3D p1 = new Vector3D(1.0, 2.0, 3.0);
        Vector3D p2 = new Vector3D(4.0, 5.0, 6.0);
        Line originalLine = new Line(p1, p2);

        // Execute revert
        Line revertedLine = originalLine.revert();

        // Verify the reverted line is not the same instance (it's a new object)
        // Note: The implementation shows 'new Line(this)', which is a copy constructor
        // In geometry, a "revert" usually implies reversing direction, 
        // but based on the provided source code: final Line reverted = new Line(this);
        // it simply returns a copy of the line.

        // Check that the origin and direction match the original 
        // (since the provided code shows it just performs a copy constructor call)
        assertEquals("Origin should be the same", originalLine.getOrigin(), revertedLine.getOrigin());
        assertEquals("Direction should be the same", originalLine.getDirection(), revertedLine.getDirection());

        // Verify properties through geometric checks
        assertTrue("Reverted line should contain the same points", originalLine.contains(p1));
        assertTrue("Reverted line should contain the same points", originalLine.contains(p2));
        assertTrue("Reverted line should be similar to original", originalLine.isSimilarTo(revertedLine));

        // Verify distance properties
        assertEquals("Distance between lines should be zero", 0.0, originalLine.distance(revertedLine), 1e-10);
    }


}

