import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for {@link Line#revert()}.
 */
public class Line_revert_TriageGen1Test {



    @Test
    public void testRevertWithDifferentCoordinates() {
        // Test with negative and zero coordinates
        Vector3D p1 = new Vector3D(0.0, 0.0, 0.0);
        Vector3D p2 = new Vector3D(-1.0, -1.0, -1.0);
        Line originalLine = new Line(p1, p2);

        Line revertedLine = originalLine.revert();

        assertEquals(originalLine.getOrigin(), revertedLine.getOrigin());
        assertEquals(originalLine.getDirection(), revertedLine.getDirection());
        assertEquals(originalLine.getAbscissa(new Vector3D(-2.0, -2.0, -2.0)), 
                     revertedLine.getAbscissa(new Vector3D(-2.0, -2.0, -2.0)), 1e-10);
    }
}
